/* Minimal DOMPurify fallback. Real DOMPurify can replace this file later. */
(function () {
  if (window.DOMPurify) return;
  window.DOMPurify = {
    sanitize: function (html) {
      var t = document.createElement("template");
      t.innerHTML = String(html || "");
      t.content.querySelectorAll("script,iframe,object,embed,link,meta").forEach(function (n) {
        n.remove();
      });
      t.content.querySelectorAll("*").forEach(function (n) {
        Array.from(n.attributes).forEach(function (a) {
          var name = a.name.toLowerCase();
          var value = String(a.value || "").trim().toLowerCase();
          if (name.indexOf("on") === 0 || value.indexOf("javascript:") === 0) {
            n.removeAttribute(a.name);
          }
        });
      });
      return t.innerHTML;
    },
  };
})();
